struct InvoiceVm: Encodable {               // stage 1: logical page
    let customer: String
    let total: String
}

func invoiceHTML(_ req: Request) async throws -> View {
    try await req.view.render("invoice", InvoiceVm(customer: "ACME", total: "42.00"))
}
